		_, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// Compute request hash: "bulk-approve.v3\n" + sorted IDs with format "<utf8_byte_length>:<id>"
		requestHash := computeRequestHash(ids)

		// Check idempotency: scope = operation + tenant + actor + key
		var existingActionRequest struct {
			requestHash string
			response    json.RawMessage
		}

		err = tx.QueryRow(ctx, `
			SELECT "requestHash", response FROM "ActionRequest"
			WHERE "tenantId"=$1 AND "actorId"=$2 AND operation='bulk-approve.v3' AND key=$3
		`, u.Tenant, u.User, key).Scan(&existingActionRequest.requestHash, &existingActionRequest.response)

		if err == nil {
			// Key exists - check if request matches
			if existingActionRequest.requestHash != requestHash {
				// Same key, different target set
				return protocol.Result{}, false, &protocol.Rejection{Status: 409}
			}
			// Same key, same targets - return cached response
			var result protocol.Result
			if err := json.Unmarshal(existingActionRequest.response, &result); err != nil {
				return protocol.Result{}, false, err
			}
			if err := tx.Commit(ctx); err != nil {
				return protocol.Result{}, false, err
			}
			return result, true, nil
		} else if err != pgx.ErrNoRows {
			return protocol.Result{}, false, err
		}

		// New request - validate and approve targets
		rows, err := tx.Query(ctx, `
			SELECT id FROM "Purchase"
			WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'
			ORDER BY id FOR UPDATE
		`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}

		eligible := []string{}
		for rows.Next() {
			var id string
			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.Result{}, false, err
			}
			eligible = append(eligible, id)
		}
		err = rows.Err()
		rows.Close()
		if err != nil {
			return protocol.Result{}, false, err
		}

		// All-or-nothing: if any target is invalid, reject all
		if len(eligible) != len(ids) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Approve all targets
		tag, err := tx.Exec(ctx, `
			UPDATE "Purchase" SET status='approved'
			WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'
		`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}

		if tag.RowsAffected() != int64(len(ids)) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Create one ApprovalAudit record per approved target
		for _, id := range ids {
			_, err := tx.Exec(ctx, `
				INSERT INTO "ApprovalAudit" ("tenantId", "purchaseId", "approvedBy", operation, "idempotencyKey", "fromStatus", "toStatus")
				VALUES ($1, $2, $3, $4, $5, $6, $7)
			`, u.Tenant, id, u.User, "bulk-approve.v3", key, "submitted", "approved")
			if err != nil {
				return protocol.Result{}, false, err
			}
		}

		// Create ActionRequest record with response
		result := protocol.Result{ApprovedIDs: ids}
		responseJSON, err := json.Marshal(result)
		if err != nil {
			return protocol.Result{}, false, err
		}

		_, err = tx.Exec(ctx, `
			INSERT INTO "ActionRequest" ("tenantId", "actorId", operation, key, "requestHash", response)
			VALUES ($1, $2, $3, $4, $5, $6)
		`, u.Tenant, u.User, "bulk-approve.v3", key, requestHash, responseJSON)
		if err != nil {
			return protocol.Result{}, false, err
		}

		if err = tx.Commit(ctx); err != nil {
			return protocol.Result{}, false, err
		}

		return result, false, nil
	}
	return protocol.HTTP(approve, fallback), nil
