			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.Result{}, false, err
			}
			eligible = append(eligible, id)
		}
		err = rows.Err()
		rows.Close()
		if err != nil {
			return protocol.Result{}, false, err
		}

		// All-or-nothing: if any target is invalid, reject all
		if len(eligible) != len(ids) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Approve all targets
		tag, err := tx.Exec(ctx, `
			UPDATE "Purchase" SET status='approved'
			WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'
		`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}

		if tag.RowsAffected() != int64(len(ids)) {
			return protocol.Result{}, false, &protocol.Rejection{Status: 409}
		}

		// Create one ApprovalAudit record per approved target
		for _, id := range ids {
			_, err := tx.Exec(ctx, `
				INSERT INTO "ApprovalAudit" ("tenantId", "purchaseId", "approvedBy", operation, "idempotencyKey", "fromStatus", "toStatus")
				VALUES ($1, $2, $3, $4, $5, $6, $7)
